    private void colors(){String[] labels=Arrays.copyOf(COLOR_NAMES,COLOR_NAMES.length+1);labels[labels.length-1]="自定义十六进制颜色";int current=COLORS.length;for(int n=0;n<COLORS.length;n++)if(a.outlineColor()==COLORS[n])current=n;new ToolDialog(a).setTitle("描边颜色").setSingleChoiceItems(labels,current,(x,n)->{if(n<COLORS.length){prefs.edit().putInt("outline_color",COLORS[n]).apply();a.refreshScreen();}else customColor(()->((AlertDialog)x).getListView().setItemChecked(COLORS.length,true));}).setNegativeButton("返回",null).show();}
