    private void legend(){
        LinearLayout c=form();
        TextView intro=a.text("左为白天，右为夜间；最右侧的数为 WMO 天气电码。这里将气象业务编码表称为“电码表”，接口字段仍称“代码”。\n\nOpen-Meteo 官方文档列出的天气代码只是 WMO 天气电码的一部分，本应用为这些代码制作了对应图标，所以编号不连续、许多数缺失是正常的。\n\nOpen-Meteo 接口返回数值天气代码，中文由本应用解释。57、67 按 WMO 范围标为“中或大冻毛毛雨”“中或大冻雨”，Open-Meteo 官方计算源码也使用这一强度范围。雷暴组（95、96、97、99）的名称参照 WMO 英文电码表，不逐字翻译 Open-Meteo 的简写。预报代码可能由模型计算，不能理解为未经处理的原始观测电码。\n\n“小或中雷暴伴冰雹”“大雷暴伴冰雹”仅由提供明确冰雹预报的模型返回，例如 DWD ICON、UKMO；是否出现取决于所用模型及其覆盖范围。",13,a.MUTED,false);
        intro.setLineSpacing(a.dp(3),1);c.addView(intro);a.gap(c,14);
        int[] supported=WeatherData.supportedCodes();int[] codes=Arrays.copyOf(supported,supported.length+1);codes[codes.length-1]=-1;
        for(int code:codes){
            LinearLayout r=a.row();r.addView(new WeatherIcon(a,code,true),a.lp(50,50));r.addView(new WeatherIcon(a,code,false),a.lp(50,50));
            r.addView(a.text(WeatherData.condition(code),14,a.INK,false),new LinearLayout.LayoutParams(0,-2,1));
            TextView number=a.text(code>=0?Integer.toString(code):"—",13,a.MUTED,false);number.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);number.setPadding(a.dp(4),0,0,0);r.addView(number,a.lp(32,50));
            c.addView(r);a.gap(c,6);
        }
        a.gap(c,8);TextView unknown=a.text("“天气未知”没有对应的 WMO 电码：当天气代码缺失、为 null、不是有效的非负整数，或服务返回了本版本尚未识别的新代码时，显示这个兜底提示及问号图标。正常返回本版本支持的代码时不会出现；它不代表一种额外的天气现象。",13,a.MUTED,false);unknown.setLineSpacing(a.dp(3),1);c.addView(unknown);a.gap(c,14);
        a.link(c,"Open-Meteo · 官方代码文档","https://open-meteo.com/en/docs#weather_variable_documentation");
        a.link(c,"WMO · 英文电码原文","https://codes.wmo.int/bufr4/codeflag/0-20-003?_view=all");
        dialog("天气图例",c);
    }
